import{_ as o,C as e,c as l,o as r,aj as s,G as i,w as m}from"./chunks/framework.Bfdr4H5E.js";const y=JSON.parse('{"title":"Money Management – Trading Plan Inclusion","description":"","frontmatter":{"outline":"deep","prev":{"text":"Money Management","link":"/trading-with-pav/money-management"},"next":{"text":"Money Management – Explanatory Notes","link":"/trading-with-pav/money-management-explanatory-notes"}},"headers":[],"relativePath":"trading-with-pav/money-management-trading-plan-inclusion.md","filePath":"trading-with-pav/money-management-trading-plan-inclusion.md"}'),d={name:"trading-with-pav/money-management-trading-plan-inclusion.md"};function u(p,n,c,h,g,f){const t=e("GraphComment"),a=e("ClientOnly");return r(),l("div",null,[n[0]||(n[0]=s('<h1 id="money-management-–-trading-plan-inclusion" tabindex="-1">Money Management – Trading Plan Inclusion <a class="header-anchor" href="#money-management-–-trading-plan-inclusion" aria-label="Permalink to &quot;Money Management – Trading Plan Inclusion&quot;">​</a></h1><ul><li><p><strong>Individual Trade Risk:</strong></p><ul><li>Position sizing is to be such that maximum risk per trade is to not exceed 1% of account equity.</li></ul></li><li><p><strong>Trading Session Money Management</strong></p><ul><li>Daily timeout is to occur at 2% drawdown from session highs.</li><li>Daily stop is to occur at 3% drawdown from session highs.</li><li>Percentage figures are calculated on the trade session highs as price amounts.</li></ul></li><li><p><strong>Business Money Management</strong></p><ul><li>I will stop trading at 20% drawdown.</li><li>I will take this trading halt as an opportunity to review my trading plan, review my trading performance with the benefit of hindsight, and return to a simulation platform until <ul><li>(a) consistent profitability is again proven in that environment, and</li><li>(b) the account balance has been replenished via other sources.</li></ul></li></ul></li><li><p><strong>A Graduated Approach to Increasing Size</strong></p><ul><li>All increases in number of contracts will be <ul><li>(a) preceded by a profitable month at the previous position size;</li><li>(b) only initiated when our equity balance allows the increase while still maintaining our individual trade risk of 1%; and</li><li>(c) proven in a sim environment through demonstration of a profitable week of trading.</li></ul></li><li>If a session stop is hit, I will consider the need for a return to the previous size and/or sim environment. If two session stops are hit, with no intermediate equity high, I must return to the previous size.</li></ul></li><li><p><strong>Income to Maintain Lifestyle</strong></p><ul><li><p>I am not in a financial position to allow full-time trading, however my work is from 10am to 5pm. This, plus my wife’s income, is sufficient to cover our expenses and maintain our current lifestyle.</p></li><li><p>I will not transition to full-time until my trading has developed to a level which can regularly provide the equivalent of twice my working income, in order to allow for capital growth and income needs.</p></li><li><p>This structure allows me to day-trade the commodities markets from the 06:00pm to 11:30pm open for a period of 4 hours, after attending work. In the morning I will allocate 1 hour for review.</p></li></ul></li></ul><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',3)),i(a,null,{default:m(()=>[i(t)]),_:1})])}const v=o(d,[["render",u]]);export{y as __pageData,v as default};
